,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' verifica_ente varchar2(1);',
' verifica_bilancio number := 0;',
'begin',
'   begin',
'        select nvl(utilizzo_sic,''N'') into verifica_ente',
'        from cons_anagrafica',
'        where id = :p2_ente;',
'       exception when no_data_found then verifica_ente := ''N'';',
'    end;',
'     select count(*) into verifica_bilancio',
'     from vw_all11_enti',
'     where id_ente = :p2_ente',
'     and anno = :p2_anno;',
'     ',
'    if (verifica_ente = ''S'' and verifica_bilancio > 0)',
'    then return TRUE;',
'    else return FALSE;',
'end if;',
'end;'))
,p_button_condition2=>'PLSQL'
