'declare',
' msg varchar2(2000);',
' esiste number;',
'begin',
'select count(*) ',
'  into esiste',
'  from cons_piacee_importi',
'  where id_ente=:P2_ente and',
'        anno=:P2_anno and',
'        (dare is not null or avere is not null);',
'if /*:P2_BILANCIO is null or',
'   :P2_ANNO is null or',
'   to_number(:P2_anno) not between to_number(to_char(sysdate,''yyyy''))-10 and to_number(to_char(sysdate,''yyyy'')) then',
