wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(33061866650702308)
,p_tabular_form_region_id=>wwv_flow_imp.id(8674756785325922)
,p_validation_name=>'verifica infra singola'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'importo_bilancio number := 0;',
'desc_conto varchar2(2000);',
'errore varchar2 (2000);',
'',
'',
'begin',
' if :APEX$ROW_STATUS = ''D'' then',
'        return null;',
'    end if;',
'   begin',
'    select nvl(importo,0) into importo_bilancio',
'    from cons_piacee_importi',
'    where anno = :p3_anno',
'    and id_ente = :p3_ente',
'    and codice_conto = :CODICE_CONTO;',
'   exception when no_data_found then importo_bilancio := -1;',
'   end;',
'  if importo_bilancio = -1',
'   then  ',
'   errore := ''Non e'''' consentito inserire infragruppo se il bilancio dell''''Ente/Azienda non e'''' stato caricato!''; ',
'   return(errore);',
'  elsif (importo_bilancio-to_number(replace(:IMPORTO_ORIGINALE,''.''))) < 0 ',
'   then',
'   Begin',
'    select codice_conto|| '' - ''||descrizione into desc_conto',
'    from cons_piacee',
'    where anno = :P3_anno',
'    and id = :CODICE_CONTO;',
'  exception when no_data_found then desc_conto := ''Conto non definibile'';  ',
'   end;',
'   errore := ''L''''importo di infragruppo inserito sul conto ''||desc_conto||'' non e'''' compatibile con la corrispondente voce di bilancio pari a Euro ''||to_char(importo_bilancio,''999G999G999D00'')||''. Verificare!'';',
'   return(errore);',
'  end if;',
'',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8688354832363528)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(8674756785325922)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Inserisci Infragruppo - Save Interactive Grid Data'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
