wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67527870799396804)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Controlla importi infra'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for r in (',
'        select',
'            t.id_conto,',
'            nvl(',
'                p.codice_conto || '' - '' || p.descrizione,',
'                ''Voce non definita''',
'            ) as voce_bilancio,',
'            t.totale_infra,',
'            nvl(b.importo, 0) as importo_bilancio,',
'            b.codice_conto as conto_bilancio',
'        from (',
'            select',
'                anno,',
'                id_ente,',
'                id_conto,',
'                sum(nvl(importo_originale, 0)) as totale_infra',
'            from cons_infragruppo',
'            where anno    = :P3_ANNO',
'              and id_ente = :P3_ENTE',
'            group by anno, id_ente, id_conto',
'        ) t',
'        left join cons_piacee_importi b',
'          on b.anno         = t.anno',
'         and b.id_ente      = t.id_ente',
'         and b.codice_conto = t.id_conto',
'        left join cons_piacee p',
'          on p.anno = t.anno',
'         and p.id   = t.id_conto',
'        where b.codice_conto is null',
'           or t.totale_infra > nvl(b.importo, 0)',
'    ) loop',
'        if r.conto_bilancio is null then',
'            raise_application_error(',
'                -20001,',
'                ''Importo di bilancio assente per la voce ''',
'                || r.voce_bilancio || ''.''',
'            );',
'        else',
'            raise_application_error(',
'                -20001,',
'                ''Il totale infragruppo della voce ''',
'                || r.voce_bilancio',
unistr('                || '' \00E8 pari a Euro '''),
'                || to_char(r.totale_infra,',
'                           ''FM999G999G999G999G990D00'')',
'                || '' e supera il bilancio di Euro ''',
'                || to_char(r.importo_bilancio,',
'                           ''FM999G999G999G999G990D00'')',
'                || ''. Ridurre gli importi inseriti.''',
'            );',
'        end if;',
'    end loop;',
'exception',
'    when others then',
'        rollback;',
'        raise;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(67527908828396805)
,p_internal_uid=>67527870799396804
);
end;
