,p_plug_name=>'Infragruppo Ente'
,p_title=>'Infragruppo &P5_DENOMINAZIONE_ENTE.'
,p_region_template_options=>'#DEFAULT#:t-Region--accent1:t-Region--scrollBody'
,p_plug_template=>wwv_flow_imp.id(6670981072264354)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select e.CODICE_CONTO||'' - ''||e.descrizione codice_conto',
',a.denominazione Ente_az_riferimento',
'  ,nvl(i.IMPORTO_ORIGINALE,0) importo_originale',
'  ,nvl((select sum(r.importo) from cons_rettifiche r where r.anno = i.anno and r.id_ente = i.id_ente and r.codice_conto = i.id_conto and nvl(r.bil_infra,''X'') = ''I'' and (r.id_ente_rif is null OR r.id_ente_rif = i.id_infra)),0) Importo_rettifica',
'  ,(nvl(i.IMPORTO_ORIGINALE,0)',
'   +',
'   nvl((select sum(r.importo) from cons_rettifiche r where r.anno = i.anno and r.id_ente = i.id_ente and r.codice_conto = i.id_conto and nvl(r.bil_infra,''X'') = ''I'' and (r.id_ente_rif is null OR r.id_ente_rif = i.id_infra)),0)',
'  ) saldo',
'  ,e.ordinamento_stampa,decode(substr(e.CODICE_CONTO,1,1),''A'',1,''P'',2,99) tipo',
'from cons_infragruppo i',
',cons_piacee e',
',cons_anagrafica a',
'where i.anno = :P5_ANNO',
'and i.id_ente = :P5_ENTE',
'and e.anno = i.anno',
'and e.id = i.ID_CONTO',
'and e.ENTE_SOCIETA = ''E''',
'and a.id = i.id_infra',
'UNION',
'select e.CODICE_CONTO||'' - ''||e.descrizione codice_conto',
',a.denominazione Ente_az_riferimento',
',0 importo_originale',
',sum(r.importo) importo_rettifica',
',sum(r.importo) saldo',
',e.ordinamento_stampa',
',decode(substr(e.CODICE_CONTO,1,1),''A'',1,''P'',2,99) tipo',
'from cons_rettifiche r',
',cons_piacee e',
',cons_anagrafica a',
'where r.anno = :P5_ANNO',
'and r.id_ente = :P5_ENTE',
'and r.codice_conto = e.id ',
'and nvl(r.bil_infra,''X'') = ''I'' ',
'and (r.anno,r.id_ente,r.codice_conto,r.ID_ENTE_RIF) not in (select x.ANNO, x.ID_ENTE, x.ID_CONTO,x.ID_INFRA  from cons_infragruppo x where x.anno = :P5_ANNO and x.id_ente = :P5_ENTE)',
'and e.anno = r.anno',
'and e.id = r.CODICE_CONTO',
'and e.ENTE_SOCIETA = ''E''',
'and a.id = r.id_ente_rif',
'group by  e.CODICE_CONTO',
',e.descrizione',
',a.denominazione',
',0',
',e.ordinamento_stampa',
',decode(substr(e.CODICE_CONTO,1,1),''A'',1,''P'',2,99)',
'order by 2,7,6;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Verifica Infragruppo'
,p_ai_enabled=>false
);
