,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.denominazione Ente_Azienda',
',p.codice_conto||'' - ''||p.DESCRIZIONE conto',
',decode(p.tipo,''A'',1,''P'',2,''CO'',3,99) tipo',
',p.ORDINAMENTO_STAMPA ordina',
',nvl(sum(nvl(i.IMPORTO_ORIGINALE,0)),0) importo_originale',
',sum((nvl(i.IMPORTO_ORIGINALE,0)',
'   +',
'   nvl((select sum(r.importo) from cons_rettifiche r where r.anno = i.anno and r.id_ente = i.id_ente and r.codice_conto = i.id_conto and nvl(r.bil_infra,''X'') = ''I'' and (r.id_ente_rif is null OR r.id_ente_rif = i.id_infra)),0)',
'  )) importo_rettificato',
'from cons_infragruppo i',
',cons_anagrafica b',
',cons_piacee p',
'where ',
'i.anno = :P5_ANNO',
'and i.id_infra = :P5_ENTE',
'and b.id = i.id_ente',
'and p.anno = i.anno',
'and p.id = i.id_conto',
'group by b.denominazione',
',p.codice_conto||'' - ''||p.DESCRIZIONE,decode(p.tipo,''A'',1,''P'',2,''CO'',3,99)',
',p.ORDINAMENTO_STAMPA',
'UNION',
'select b.denominazione Ente_Azienda',
',p.codice_conto||'' - ''||p.DESCRIZIONE conto',
',decode(p.tipo,''A'',1,''P'',2,''CO'',3,99) tipo',
',p.ORDINAMENTO_STAMPA ordina',
',0 importo_originale',
',sum(r.importo) importo_rettificato',
'--,sum(r.importo) saldo',
'from cons_rettifiche r',
',cons_piacee p',
',cons_anagrafica b',
'where r.anno = :P5_ANNO',
'and r.id_ente_rif = :P5_ENTE',
'and r.codice_conto = p.id ',
'and nvl(r.bil_infra,''X'') = ''I'' ',
'and (r.anno,r.id_ente_rif,r.codice_conto,r.ID_ENTE) not in (select x.ANNO, x.ID_INFRA, x.ID_CONTO,x.id_ente  from cons_infragruppo x where x.anno = :P5_ANNO and x.id_infra = :P5_ENTE)',
'and p.anno = r.anno',
'and p.ENTE_SOCIETA = ''E''',
'and b.id = r.ID_ENTE',
'group by  b.denominazione',
',p.codice_conto||'' - ''||p.DESCRIZIONE',
