wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67528370824396809)
,p_process_sequence=>8
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(9435082450248561)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Memorizza gruppi rettificati'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    procedure aggiungi_gruppo(',
'        p_anno  number,',
'        p_ente  number,',
'        p_conto number,',
'        p_tipo  varchar2,',
'        p_rif   number',
'    ) is',
'    begin',
'        apex_collection.add_member(',
'            p_collection_name => ''P6_GRUPPI_RETTIFICHE'',',
'            p_c001 => p_tipo,',
'            p_n001 => p_anno,',
'            p_n002 => p_ente,',
'            p_n003 => p_conto,',
'            p_n004 => case when p_tipo = ''I'' then p_rif end',
'        );',
'    end;',
'begin',
'    -- Per modifiche e cancellazioni memorizza il gruppo',
'    -- originale, prima che il DML modifichi la tabella.',
'    if :APEX$ROW_STATUS in (''U'', ''D'') then',
'        for r in (',
'            select anno, id_ente, codice_conto,',
'                   bil_infra, id_ente_rif',
'            from cons_rettifiche',
'            where rowid = :ROWID',
'              and nvl(flag_bilancio, ''C'') <> ''C''',
'        ) loop',
'            aggiungi_gruppo(',
'                r.anno,',
'                r.id_ente,',
'                r.codice_conto,',
'                r.bil_infra,',
'                r.id_ente_rif',
'            );',
'        end loop;',
'    end if;',
'',
'    -- Per inserimenti e modifiche memorizza il nuovo gruppo.',
'    if :APEX$ROW_STATUS in (''C'', ''U'')',
'       and nvl(:FLAG_BILANCIO, ''C'') <> ''C''',
'    then',
'        aggiungi_gruppo(',
'            :ANNO,',
'            :ID_ENTE,',
'            :CODICE_CONTO,',
'            :BIL_INFRA,',
'            :ID_ENTE_RIF',
'        );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(67528125247396807)
,p_only_for_changed_rows=>'N'
,p_security_scheme=>wwv_flow_imp.id(33471789755956485)
,p_internal_uid=>67528370824396809
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(33063005448702320)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(9435082450248561)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Rettifiche Bil Infra - Save Interactive Grid Data'
,p_attribute_01=>'REGION_SOURCE'
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_attribute_08=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_security_scheme=>wwv_flow_imp.id(33471789755956485)
,p_internal_uid=>33063005448702320
