wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(67528038133396806)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Controlla rettifiche'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    function euro(p_importo number) return varchar2 is',
'    begin',
'        return to_char(',
'            p_importo,',
'            ''FM999G999G999G999G990D00''',
'        );',
'    end;',
'begin',
'    for r in (',
'        with rettifiche as (',
'            select',
'                anno,',
'                id_ente,',
'                codice_conto,',
'                bil_infra,',
'                case',
'                    when bil_infra = ''I'' then id_ente_rif',
'                end as controparte,',
'                sum(importo) as saldo_rettifiche',
'            from cons_rettifiche',
'            where anno = :P6_ANNO',
'              and nvl(flag_bilancio, ''C'') <> ''C''',
'              and bil_infra in (''B'', ''I'')',
'            group by',
'                anno,',
'                id_ente,',
'                codice_conto,',
'                bil_infra,',
'                case',
'                    when bil_infra = ''I'' then id_ente_rif',
'                end',
'        ),',
'        importi_base as (',
'            -- Bilancio: una voce per anno ed ente.',
'            select',
'                anno,',
'                id_ente,',
'                codice_conto,',
'                ''B'' as tipo,',
'                cast(null as number) as controparte,',
'                nvl(importo, 0) as importo_base',
'            from cons_piacee_importi',
'            where anno = :P6_ANNO',
'',
'            union all',
'',
'            -- Infragruppo: stessa voce e specifica controparte.',
'            select',
'                anno,',
'                id_ente,',
'                id_conto as codice_conto,',
'                ''I'' as tipo,',
'                id_infra as controparte,',
'                sum(nvl(importo_originale, 0)) as importo_base',
'            from cons_infragruppo',
'            where anno = :P6_ANNO',
'            group by anno, id_ente, id_conto, id_infra',
'        )',
'        select',
'            t.bil_infra,',
'            t.saldo_rettifiche,',
'            b.importo_base,',
'            b.tipo as tipo_base,',
'            nvl(',
'                p.codice_conto || '' - '' || p.descrizione,',
'                ''Voce non definita''',
'            ) as voce,',
'            nvl(a.denominazione, ''Ente non definito'') as ente,',
'            nvl(c.denominazione, ''Controparte non definita'')',
'                as controparte',
'        from rettifiche t',
'        left join importi_base b',
'          on b.anno         = t.anno',
'         and b.id_ente      = t.id_ente',
'         and b.codice_conto = t.codice_conto',
'         and b.tipo         = t.bil_infra',
'         and (',
'             t.bil_infra = ''B''',
'             or b.controparte = t.controparte',
'         )',
'        left join cons_piacee p',
'          on p.anno = t.anno',
'         and p.id   = t.codice_conto',
'        left join cons_anagrafica a',
'          on a.id = t.id_ente',
'        left join cons_anagrafica c',
'          on c.id = t.controparte',
'        where exists (',
'    select 1',
'    from apex_collections g',
'    where g.collection_name = ''P6_GRUPPI_RETTIFICHE''',
'      and g.n001 = t.anno',
'      and g.n002 = t.id_ente',
'      and g.n003 = t.codice_conto',
'      and g.c001 = t.bil_infra',
'      and (',
'          t.bil_infra = ''B''',
'          or g.n004 = t.controparte',
'      )',
')',
'and (',
'    b.tipo is null',
'    or b.importo_base + t.saldo_rettifiche < 0',
')',
'    ) loop',
'        if r.tipo_base is null then',
'            raise_application_error(',
'                -20001,',
'                ''Impossibile rettificare la voce ''',
'                || r.voce || '' di '' || r.ente',
'                || case',
'                       when r.bil_infra = ''I''',
'                       then '' verso '' || r.controparte',
'                   end',
'                || '': manca il corrispondente importo di ''',
'                || case',
'                       when r.bil_infra = ''B'' then ''bilancio''',
'                       else ''infragruppo''',
'                   end',
'                || ''.''',
'            );',
'        else',
'            raise_application_error(',
'                -20001,',
'                ''Le rettifiche della voce ''',
'                || r.voce || '' di '' || r.ente',
'                || case',
'                       when r.bil_infra = ''I''',
'                       then '' verso '' || r.controparte',
'                   end',
'                || '' hanno un saldo di Euro ''',
'                || euro(r.saldo_rettifiche)',
'                || '', a fronte di un importo ''',
'                || case',
'                       when r.bil_infra = ''B'' then ''di bilancio''',
'                       else ''infragruppo verso la controparte indicata''',
'                   end',
'                || '' di Euro ''',
'                || euro(r.importo_base)',
'                || ''. L''''importo risultante sarebbe negativo: Euro ''',
'                || euro(r.importo_base + r.saldo_rettifiche)',
'                || ''. Verificare le rettifiche.''',
'            );',
'        end if;',
'    end loop;',
'exception',
'    when others then',
'        rollback;',
'        raise;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(67528125247396807)
,p_security_scheme=>wwv_flow_imp.id(33471789755956485)
,p_internal_uid=>67528038133396806
);
