,p_button_action=>'SUBMIT'
,p_button_template_options=>'#DEFAULT#:t-Button--success:t-Button--iconLeft'
,p_button_template_id=>wwv_flow_imp.id(6744651003264377)
,p_button_image_alt=>'GENERA SCRITTURE'
,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'conto number := 0;',
'conta_scritt number := 0;',
'',
'begin',
'select nvl(count(*),0) into conto',
'from cons_diff_consolidamento',
'where anno = :P7_ANNO',
'and id_conto_diff is null',
'and nvl(diff_consolidamento,0) <> 0;',
'',
'select nvl(count(*),0) into conta_scritt',
'from cons_ana_contabile',
'where anno = :P7_ANNO',
'and nvl(flag_dc,''N'') <> ''N''',
'and nvl(QUOTA_PARTECIPAZIONE,0) > 0',
'and nvl(PERC_PARTECIPAZIONE,0) > 0;',
'',
'if (conto = 0 and :P7_VALORE_DIFF = 0 and conta_scritt = 0)',
'then return(true);',
'else return(false);',
'end if;',
'',
'end;'))
,p_button_condition2=>'PLSQL'
,p_button_condition_type=>'FUNCTION_BODY'
,p_icon_css_classes=>'fa-edit'
,p_grid_new_row=>'N'
,p_grid_column_span=>2
,p_grid_column=>5
);
