,p_prompt=>'Anno'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d.anno,d.anno p_anno',
'from cons_dati_generali d',
',cons_utenti u',
'where (nvl(d.attivo,''N'') = ''S''',
'and d.data_f_carica is null',
'and u.id_ente <> 1',
'and upper(u.user_name) = upper(:app_user) ',
')',
'OR',
'(u.id_ente = 1',
'and upper(u.user_name) = upper(:app_user) ',
') -- solo per Regione'))
,p_lov_display_null=>'YES'
,p_cHeight=>1
,p_begin_on_new_line=>'N'
,p_colspan=>1
,p_grid_column=>1
,p_field_template=>wwv_flow_imp.id(6741926341264377)
