);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(10096249630254312)
,p_name=>'P7_VERIFICA_CONTO_DIFF'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(10096339320254313)
,p_prompt=>'Verifica Conto Differenze'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'dare_avere varchar2(1);',
'messaggio varchar2(2000) := '''';',
'conta number := 0;',
'',
'begin',
':P7_VALORE_DIFF := 0;',
'',
'for p in (select denominazione,nvl(diff_consolidamento,0) diff, id_conto_diff conto',
'          from cons_diff_consolidamento',
'          where anno = :P7_ANNO',
'          and id_conto_diff is not null) loop',
'',
' begin',
'   select D_A into dare_avere',
'   from cons_piacee',
'   where anno = :P7_ANNO',
'   and nvl(ente_societa,''X'') = ''E''',
'   and id = p.conto;',
' exception when no_data_found then dare_avere := ''X'';',
' end; ',
'',
'if dare_avere = ''X''',
unistr(' then :P7_VERIFICA_CONTO_DIFF := ''Il conto per compensare la differenza non \00E8 utilizzabile''||chr(10);'),
'conta := conta + 1;',
' elsif (dare_avere = ''D'' and p.diff < 0) ',
' then messaggio := messaggio||(p.denominazione||'' differenza < 0 va usato un conto di Passivo o di Ricavo''||chr(10));',
'conta := conta + 1;',
' elsif dare_avere = ''A'' and p.diff > 0',
' then messaggio := messaggio||p.denominazione||'' differenza > 0 va usato un conto di Attivo o di Costo''||chr(10);',
'conta := conta + 1;',
' end if;',
'',
'end loop;',
'',
':P7_VALORE_DIFF := conta;',
'return(messaggio);',
'',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_display_when=>'P7_VERIFICA_CONTO_DIFF'
,p_display_when_type=>'ITEM_IS_NOT_ZERO'
,p_field_template=>wwv_flow_imp.id(6742009815264377)
,p_item_template_options=>'#DEFAULT#'
,p_attribute_01=>'Y'
,p_attribute_02=>'VALUE'
,p_attribute_04=>'Y'
,p_attribute_05=>'PLAIN'
);
