,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Elabora differenze'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'-- FF 15/11/2024 se non sono state generate scritture per l''id_ana e l''anno considerato ripuliamo la cons_diff_consolidamento per l''anno considerato',
'delete cons_diff_consolidamento d',
'where d.anno = :P7_ANNO',
'and d.id_ana in (select x.id_ana from cons_ana_contabile x where x.anno = :P7_ANNO and nvl(flag_dc,''N'') = ''N'' and  nvl(x.quota_partecipazione, 0) > 0',
'                        AND nvl(x.perc_partecipazione, 0) > 0);',
'commit;',
'',
' insert into cons_diff_consolidamento (ANNO, ID_ANA, DENOMINAZIONE, PERC_PARTECIP, QUOTA_PARTECIP,     PATRIMONIO_NETTO, DIFF_CONSOLIDAMENTO)',
' select ANNO, ID_ANA, DENOMINAZIONE, PERC_PARTECIPAZIONE, QUOTA_PARTECIPAZIONE, PATRIMONIO_NETTO, DIFF_CONS',
' from vw_diff_consolidamento',
' where anno = :P7_ANNO;',
'commit;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(10095628166254306)
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select * ',
'from cons_diff_consolidamento',
'where anno = :P7_ANNO;'))
,p_process_when_type=>'NOT_EXISTS'
,p_process_success_message=>'Differenze di Consolidamento elaborate.'
,p_internal_uid=>10095789442254307
);
