wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(10097311298254323)
,p_plug_name=>'Visualizza Rettificato'
,p_title=>'Bilancio Rettificato &P9_DESC_ENTE.'
,p_region_template_options=>'#DEFAULT#:t-Region--accent4:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6670981072264354)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select c.tipo,c.codice_conto, c.descrizione,c.importo',
',(select nvl(x.IMPORTO,0)',
'from vw_bilanci_enti_rettificati x',
'where x.anno= :P9_ANNO - 1',
'and x.id_ente = :P9_ENTE',
'and x.CODICE_CONTO = c.CODICE_CONTO) importo1',
',p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_rettificati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'')in (''N'',''S'')',
'UNION',
'select c.tipo,c.codice_conto, c.descrizione,totale_conto_rettificato(:P9_ANNO,c.codice_conto,:P9_ENTE) importo,totale_conto_rettificato(:P9_ANNO-1,c.codice_conto,:P9_ENTE) importo1,p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_rettificati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'')=''T''',
'UNION',
'select c.tipo,c.codice_conto, c.descrizione',
',(select sum(nvl(x.importo,0))',
'from vw_bilanci_enti_rettificati x',
',cons_piacee y',
'where x.anno = :P9_ANNO',
'and x.id_ente = :P9_ENTE',
'and substr(x.codice_conto,1,length(c.codice_conto)) = c.codice_conto',
'and y.anno = x.anno',
'and y.id = x.ID_CONTO',
'and nvl(y.aggregato,''X'')= ''N'') importo',
',(select sum(nvl(x.importo1,0))',
'from vw_bilanci_enti_rettificati x',
',cons_piacee y',
'where x.anno = :P9_ANNO',
'and x.id_ente = :P9_ENTE',
'and substr(x.codice_conto,1,length(c.codice_conto)) = c.codice_conto',
'and y.anno = x.anno',
'and y.id = x.ID_CONTO',
'and nvl(y.aggregato,''X'')= ''N'')IMPORTO1',
',p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_rettificati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'')= ''P''',
'order by tipo,ORDINAMENTO_STAMPA;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
,p_prn_paper_size=>'A4'
,p_prn_width=>297
,p_prn_height=>210
,p_prn_orientation=>'HORIZONTAL'
