'select c.tipo,c.codice_conto, c.descrizione,c.importo',
',(select nvl(x.IMPORTO,0)',
'from vw_bilanci_enti_nettizzati x',
'where x.anno= :P9_ANNO - 1',
'and x.id_ente = :P9_ENTE',
'and x.CODICE_CONTO = nvl(p.conto_prec,c.CODICE_CONTO)) IMPORTO1',
',p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_nettizzati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'') = ''N''',
'UNION',
'select c.tipo,c.codice_conto, c.descrizione,null,null,p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_nettizzati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'') = ''S''',
'UNION',
'select c.tipo,c.codice_conto, c.descrizione,totale_conto_netto(:P9_ANNO,c.codice_conto,:P9_ENTE) importo,totale_conto_netto(:P9_ANNO-1,nvl(p.conto_prec,c.CODICE_CONTO),:P9_ENTE) importo1,p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_nettizzati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'')=''T''',
'UNION',
'select c.tipo,c.codice_conto, c.descrizione',
',(select sum(nvl(x.importo,0))',
'from vw_bilanci_enti_nettizzati x',
',cons_piacee y',
'where x.anno = :P9_ANNO',
'and x.id_ente = :P9_ENTE',
'and substr(x.codice_conto,1,length(c.codice_conto)) = c.codice_conto',
'and y.anno = x.anno',
'and y.id = x.ID_CONTO',
'and nvl(y.aggregato,''X'')= ''N'') importo',
',(select sum(nvl(x.importo,0))',
'from vw_bilanci_enti_nettizzati x',
',cons_piacee y',
'where x.anno = :P9_ANNO-1',
'and x.id_ente = :P9_ENTE',
'and substr(x.codice_conto,1,length(c.codice_conto)) = c.codice_conto',
'and y.anno = x.anno',
'and y.id = x.ID_CONTO',
'and nvl(y.aggregato,''X'')= ''N'')IMPORTO1',
',p.attributo_stampa,p.ordinamento_stampa',
'from vw_bilanci_enti_nettizzati c',
',cons_piacee p',
'where c.anno = :P9_ANNO',
'and c.id_ente = :P9_ENTE',
'and c.anno = p.anno',
'and c.ID_CONTO = p.id',
'and nvl(p.aggregato,''X'')= ''P''',
'order by tipo,ORDINAMENTO_STAMPA;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'MILLIMETERS'
