,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' righe_presenti number:= 0;',
'begin',
' select nvl(sum(nvl(importo,0)),0) into righe_presenti',
' from cons_bil_consolidato',
' where anno = :P11_ANNO;',
'',
'if righe_presenti = 0',
' then return(false);',
' elsif verifica_consolidato(:P11_ANNO) <> 0',
'  then return(false);',
'  else return(true);',
'end if;',
'',
'end;'))
