,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Stampa SP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' l_htmlstr varchar2(32767);',
' rs varchar2(2000);',
' ele_cap varchar2(2000);',
' nome_stampa varchar2(20);',
' wID number;',
' wurl varchar2(200);',
'',
'begin',
'',
'SELECT ID_TMP_PARAM_REPORTS_2.NEXTVAL INTO wID FROM DUAL;',
'',
'',
'insert into TMP_PARAM_REPORTS_2 (',
'  ID',
'  ,DATA',
'  ,USER_ID',
'  ,USER_NAME',
'  ,DESCRIZIONE',
'  ,INTESTAZIONE01',
'  ,INTESTAZIONE02',
'  ,INTESTAZIONE_DESTRA',
'  ,P01_ANNO',
'  ,P01_ANNO_DESC',
'  ,NOME_REPORTS',
')',
'values (',
'  wID',
'  ,sysdate',
'  ,100 ',
'  ,:APP_USER',
'  ,''Stato Patrimoniale Consolidato''',
'  ,''Attivo''',
'  ,''Passivo''',
'  ,''Allegato 11 - Rendiconto della Gestione''',
'  ,:P11_ANNO',
'  ,''Anno Finanziario''',
'  ,''CONSSP''',
');',
'commit;',
'nome_stampa := ''CONSSP'';',
'',
'',
' select jasper_report_url into wurl from application_parameter;',
'',
'  htp.init;',
'    ',
'    l_htmlstr   :=',
'               ''<HTML><BODY onLoad="document.LoginForm.submit();">''  ',
'                || ''<FORM target="_blank" ACTION="''',
'                ||  wurl',
'                || ''" METHOD="GET" NAME="LoginForm">'' ',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''key''',
'                || ''" VALUE=4oQkN7MCgFWNEXTz>''',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''nome-report''',
'                || ''" VALUE='' ||nome_stampa|| '' >''',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''param''',
'                || ''" VALUE='' ||wID|| ''>''     ',
'                || ''</FORM></BODY></HTML>'';',
'',
'',
'',
'',
'    htp.p(l_htmlstr); ',
'',
':p11_stampa:=null;',
'exception',
' when others then null;',
'   htp.init;',
'   owa_util.redirect_url(''f?p=''|| :APP_ID || '':11:'' || :APP_SESSION); ',
'   htmldb_application.g_unrecoverable_error := true; ',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(10984691687600110)
