wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11192655606982825)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Stampa SP'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' l_htmlstr varchar2(32767);',
' rs varchar2(2000);',
' ele_cap varchar2(2000);',
' nome_stampa varchar2(20);',
' wID number;',
' wurl varchar2(200);',
'',
'begin',
'',
'SELECT ID_TMP_PARAM_REPORTS_2.NEXTVAL INTO wID FROM DUAL;',
'',
'',
'insert into TMP_PARAM_REPORTS_2 (',
'  ID',
'  ,DATA',
'  ,USER_ID',
'  ,USER_NAME',
'  ,DESCRIZIONE',
'  ,INTESTAZIONE01',
'  ,INTESTAZIONE02',
'  ,INTESTAZIONE_DESTRA',
'  ,P01_ANNO',
'  ,P01_ANNO_DESC',
'  ,NOME_REPORTS',
')',
'values (',
'  wID',
'  ,sysdate',
'  ,100 ',
'  ,:APP_USER',
'  ,''Stato Patrimoniale''',
'  ,''Rendiconto Consolidato Giunta - Consiglio''',
'  ,NULL',
'  ,''Allegato 12 - Rendiconto della Gestione''',
'  ,:P12_ANNO',
'  ,''Anno Finanziario''',
'  ,''GCSP''',
');',
'commit;',
'nome_stampa := ''GCSP'';',
'',
'',
' select jasper_report_url into wurl from application_parameter;',
'',
'  htp.init;',
'    ',
'    l_htmlstr   :=',
'               ''<HTML><BODY onLoad="document.LoginForm.submit();">''  ',
'                || ''<FORM target="_blank" ACTION="''',
'                ||  wurl',
'                || ''" METHOD="GET" NAME="LoginForm">'' ',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''key''',
'                || ''" VALUE=4oQkN7MCgFWNEXTz>''',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''nome-report''',
'                || ''" VALUE='' ||nome_stampa|| '' >''',
'                || ''<INPUT TYPE="HIDDEN" NAME="''',
'                || ''param''',
'                || ''" VALUE='' ||wID|| ''>''     ',
'                || ''</FORM></BODY></HTML>'';',
'',
'',
'',
'',
'    htp.p(l_htmlstr); ',
'',
':p12_stampa:=null;',
'exception',
' when others then null;',
'   htp.init;',
'   owa_util.redirect_url(''f?p=''|| :APP_ID || '':12:'' || :APP_SESSION); ',
'   htmldb_application.g_unrecoverable_error := true; ',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(11191628457982825)
,p_process_when=>'P12_STAMPA'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'1'
,p_internal_uid=>11192655606982825
);
