,p_plug_template=>wwv_flow_imp.id(6670981072264354)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'from(',
'select a.denominazione,t.codice_conto||'' - ''||t.descrizione descrizione,t.importo',
',(select x.importo ',
'from vw_bilanci_enti_nett_tot x ',
'where x.anno = t.anno-1 ',
'and x.codice_conto = t.codice_conto',
'and x.id_ente = t.id_ente) importo_prec ',
',rank() over ( partition by t.codice_conto,t.descrizione order by t.importo desc) rank',
'from vw_bilanci_enti_nett_tot t',
',cons_anagrafica a',
'where t.anno = :P13_ANNO',
'and a.id = t.id_ente',
'and nvl(t.importo,0) <> 0',
'order by t.codice_conto,abs(t.importo) desc)',
'WHERE rank <= 6;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Nota Integrativa'
,p_ai_enabled=>false
);
