wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8324215814532513)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Import Bilancio'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
' a_numero number;',
' esiste_bilancio number := 0;',
'begin',
'if :P2_INTEGRATO = ''S''',
'   and (',
'       nvl(:P9999_ENTE, ''0'') <> ''1''',
'       or nvl(:P2_ENTE, ''0'') <> ''1''',
'   )',
'then',
'    raise_application_error(',
'        -20001,',
'        ''Import integrato non consentito per l''''utente o per l''''ente selezionato.''',
'    );',
'end if;',
'if nvl(:P2_INTEGRATO,''N'') = ''S''',
'then ',
'delete cons_bilancio_integrato',
' where ANNO=:P2_ANNO and',
'       ID_ENTE=:P2_ENTE;',
'insert into cons_bilancio_integrato',
' (ANNO,ID_ENTE,CODICE_CONTO,IMPORTO,DATA_CARICAMENTO)',
'select :P2_ANNO,:P2_ENTE, c001, round(to_number(replace(nvl(c003,''0''),''.'','','')),2),sysdate',
'  from APEX_collections',
'  WHERE collection_name = ''CARICA BILANCI'';',
unistr('    --    and seq_id>1; dovrebbe gi\00E0 escludere la testata    '),
'   begin',
'    select count(*) into esiste_bilancio',
'    from cons_bilancio_integrato',
'    where ANNO=:P2_ANNO;',
'    exception when no_data_found then esiste_bilancio:=0;',
'    end;',
'    if esiste_bilancio > 0',
'    then',
'        delete cons_piacee_importi_integr',
'         where ANNO=:P2_ANNO and',
'               ID_ENTE=:P2_ENTE;',
'        insert into cons_piacee_importi_integr',
'          (ANNO,ID_ENTE,CODICE_CONTO,IMPORTO,IMPORTO1)',
'        select :P2_ANNO,:P2_ENTE,p.id,b.IMPORTO,b.IMPORTO1',
'         from cons_piacee p,cons_anagrafica a,cons_bilancio_integrato b',
'         where a.id=:P2_ENTE and',
'               p.anno=:P2_ANNO and',
'               p.ente_societa=a.tipo and',
'               b.ANNO(+)=p.anno and',
'               B.CODICE_CONTO(+)=p.CODICE_CONTO and',
'               b.ID_ENTE(+)=:P2_ENTE;',
'        esiste_bilancio := 0;',
'    end if;',
'else',
' delete cons_bilanci',
' where ANNO=:P2_ANNO and',
'       ID_ENTE=:P2_ENTE;',
'insert into cons_bilanci',
' (ANNO,ID_ENTE,CODICE_CONTO,IMPORTO,DATA_CARICAMENTO)',
'select :P2_ANNO,:P2_ENTE, c001, round(to_number(replace(nvl(c003,''0''),''.'','','')),2), sysdate',
'  from APEX_collections',
'  WHERE collection_name = ''CARICA BILANCI''',
unistr('    ;--    and seq_id>1; dovrebbe gi\00E0 escludere la testata'),
'   begin',
'    select count(*) into esiste_bilancio',
'    from cons_bilanci',
'    where ANNO=:P2_ANNO and',
'           ID_ENTE=:P2_ENTE;',
'    exception when no_data_found then esiste_bilancio:=0;',
'    end;',
'    if esiste_bilancio > 0',
'    then',
'    delete cons_piacee_importi',
'     where ANNO=:P2_ANNO and',
'           ID_ENTE=:P2_ENTE;',
'    insert into cons_piacee_importi',
'      (ANNO,ID_ENTE,CODICE_CONTO,IMPORTO,IMPORTO1)',
'    select :P2_ANNO,:P2_ENTE,p.id,b.IMPORTO,b.IMPORTO1',
'     from cons_piacee p,cons_anagrafica a,cons_bilanci b ',
'     where a.id=:P2_ENTE and',
'           p.anno=:P2_ANNO and',
'           p.ente_societa=a.tipo and',
'           b.ANNO(+)=p.anno and',
'           B.CODICE_CONTO(+)=p.CODICE_CONTO and',
'           b.ID_ENTE(+)=:P2_ENTE;',
'    end if;',
'end if;',
'',
'BEGIN',
'    APEX_COLLECTION.DELETE_COLLECTION(',
'        p_collection_name => ''CARICA BILANCI''',
'    );',
'END;',
':P2_INTEGRATO := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(8451333861567346)
,p_internal_uid=>8324215814532513
);
