wwv_flow_imp_page.create_page(
 p_id=>256
,p_name=>'Riaccertamenti Uffici Dettaglio'
,p_alias=>'RIACCERTAMENTI-UFFICI-DETTAGLIO'
,p_page_mode=>'MODAL'
,p_step_title=>'Riaccertamenti Uffici Dettaglio'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function parseItalianNumber(numString) {',
'    if (!numString) {',
'        return 0; // Gestisce valori nulli o vuoti',
'    }',
'    // Rimuove tutti i punti (separatori delle migliaia)',
'    numString = numString.replace(/\./g, '''');',
'    // Sostituisce la virgola (separatore decimale) con un punto',
'    numString = numString.replace(/,/g, ''.'');',
'    return parseFloat(numString);',
'}',
'',
'',
'function importi_ufficio(triggeredItemId) {',
'    var item1_val = parseItalianNumber($v(''P256_RESIDUO'')); // Il tuo Item1 fisso',
'',
'    var items = [',
'        ''P256_IMPORTO_A_RESIDUO'',',
'        ''P256_IMPORTO_DA_ELIMINARE'',',
'        ''P256_IMPORTO_RIACCERTAMENTO1'',',
'        ''P256_IMPORTO_RIACCERTAMENTO2'',',
'        ''P256_IMPORTO_RIACCERTAMENTO3''',
'    ];',
'    ',
unistr('    // Controlliamo se l''item cliccato \00E8 vuoto.'),
unistr('    // Se NON \00E8 vuoto, usciamo immediatamente senza fare nulla.'),
unistr('    if ($v(triggeredItemId)) { // $v(item_id) restituisce il valore dell''item. Se non \00E8 vuoto, \00E8 true'),
'        console.log("Item " + triggeredItemId + " is not empty. No action taken.");',
'        return; ',
'    }',
'',
unistr('    // A questo punto, sappiamo che l''item cliccato \00E8 vuoto e va popolato.'),
'',
'    var somma_altri_item = 0; // Inizializza la somma di TUTTI gli altri item',
'',
'    // Itera su tutti gli item per sommare i valori di quelli che NON sono l''item cliccato',
'    for (var i = 0; i < items.length; i++) {',
'        var current_item_id = items[i];',
'        ',
unistr('        // Se l''item corrente NON \00E8 l''item che ha scatenato l''evento'),
'        if (current_item_id !== triggeredItemId) {',
'            var current_item_string_val = $v(current_item_id);',
unistr('            // Aggiungi il valore solo se l''item non \00E8 vuoto (o 0,00)'),
'            if (current_item_string_val) { // Se l''item ha un valore',
'                somma_altri_item += parseItalianNumber(current_item_string_val);',
'                console.log("Added " + parseItalianNumber(current_item_string_val) + " from " + current_item_id + " to somma_altri_item.");',
'            }',
'        }',
'    }',
'',
'    // Calcoliamo il valore per l''item cliccato',
'    var nuovo_valore = item1_val - somma_altri_item;',
'    $s(triggeredItemId, nuovo_valore); // Popola l''item cliccato',
'    console.log("Populated " + triggeredItemId + " with " + nuovo_valore + " (based on total sum of others).");',
'',
'    // La funzione termina qui, nessun ricalcolo per gli item successivi o per le modifiche.',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.highlight-lov-bg {',
'    background-color: #FCD86E !important; /* Un giallo tenue. Puoi scegliere il tuo colore. */',
unistr('    transition: background-color 0.4s ease-in-out; /* Rende la transizione pi\00F9 fluida (opzionale) */'),
'}'))
,p_step_template=>wwv_flow_imp.id(6579476120264329)
,p_page_template_options=>'#DEFAULT#:ui-dialog--stretch'
,p_protection_level=>'C'
,p_page_component_map=>'02'
);
