wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(75780712037945742)
,p_plug_name=>'Beneficiari'
,p_parent_plug_id=>wwv_flow_imp.id(73231007152681298)
,p_region_template_options=>'#DEFAULT#:t-Region--accent10:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(6670981072264354)
,p_plug_display_sequence=>110
,p_plug_display_point=>'SUB_REGIONS'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'ftrub.ANNO_BILANCIO_RIACCERTAMENTO,',
'ftrub.DOC_ID,',
'ftrub.ID_ANA,',
'ftrub.ID_SEDE,',
'ftrub.IMPORTO,',
'(',
'    SELECT nvl(a.denominazione, a.cognome || '' '' || a.nome) || '' - '' || nvl(a.partita_iva, a.codice_fiscale)',
'    FROM FIN_T_ANAGRAFICA a WHERE a.id = ftrub.ID_ANA',
'  ) AS BENEFICIARIO,',
'  (',
'    SELECT s.nome_sede || '' - '' || s.indirizzo || '' ('' || c.descrizione || '' - '' || s.cap_sede || '')''',
'    FROM FIN_T_ANA_SEDI s, FIN_T_COMUNI c',
'    WHERE s.id_ana = ftrub.ID_ANA AND s.id_sede = ftrub.ID_SEDE AND s.id_comune_sede = c.id',
'  ) AS SEDE',
'FROM',
'FIN_T_RIACCERTAMENTI_UFF_BEN ftrub',
'WHERE',
'ftrub.DOC_ID = :P256_DOC_ID',
'AND ftrub.ANNO_BILANCIO_RIACCERTAMENTO = :P256_ANNO_BILANCIO'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'FROM fin_t_riaccertamenti_uff_ben',
'WHERE anno_bilancio_riaccertamento = :P256_ANNO_BILANCIO',
'and doc_id = :P256_DOC_ID'))
