wwv_flow_imp_page.create_report_columns(
 p_id=>wwv_flow_imp.id(43863694792324365)
,p_query_column_id=>1
,p_column_alias=>'ELIMINA'
,p_column_display_sequence=>10
,p_column_heading=>'Elimina'
,p_use_as_row_header=>'N'
,p_column_link=>'javascript:apex.confirm(''Confermi eliminazione ?'', {request :  ''DEL_FILE'',  set : {''P256_DEL_FILE'':''#ELIMINA#''}});'
,p_column_linktext=>'<span class="fa fa-file-x" aria-hidden="true"></span>'
,p_column_alignment=>'CENTER'
,p_disable_sort_column=>'N'
,p_display_when_cond_type=>'EXISTS'
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--la colonna viene visualizzata a seconda dello stato della richiesta',
'select 1',
'from fin_t_riaccertamenti_uffici ftr',
'where ftr.doc_id = :P256_DOC_ID',
'and (',
'    exists (',
'        select 1 ',
'        from fin_t_ric_abilitazione ftra ',
'        where ftra.user_id = apex_procedure.getIdUtente(:APP_USER)',
'         and ftra.ufficio = ftr.ufficio',
'          and ftra.ruolo_richiesta in (''R'',''DIRIGENTE'')',
'          and nvl(ftr.stato,0) = 0',
'    )',
'    or',
'    exists (',
'        select 1 ',
'        from fin_t_ric_abilitazione ftra ',
'        where ftra.user_id = apex_procedure.getIdUtente(:APP_USER)',
'          and nvl(ftr.stato,0)<=1',
'          and substr(ftra.ufficio,1,2) = substr(ftr.ufficio,1,2) and ftra.ruolo_richiesta = ''D'' ',
'                ',
'    )',
'    or',
'    exists (',
'        select 1 ',
'        from fin_t_ric_abilitazione ftra ',
'        where ftra.user_id = apex_procedure.getIdUtente(:APP_USER)',
'          and nvl(ftr.stato,0)>1',
'          and ftra.ruolo_richiesta = ''G''',
'           )',
')'))
,p_derived_column=>'N'
,p_include_in_export=>'Y'
);
