wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(73269328066681240)
,p_name=>'P256_CAPITOLO_RIACCERTAMENTO1'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>160
,p_item_plug_id=>wwv_flow_imp.id(73706666484805542)
,p_item_source_plug_id=>wwv_flow_imp.id(73231007152681298)
,p_prompt=>'Capitolo'
,p_source=>'CAPITOLO_RIACCERTAMENTO1'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select  distinct   fta.eu||fta.codice||'' - ''||fta.descrizione||'' - ''||decode(ftsc.titolarita,''T'',''TITOLARE'',''C'',''CONTITOLARE'') descrizione, fta.eu||fta.codice codice',
'from 	fin_t_articoli fta, fin_t_strutture_capitoli ftsc, fin_t_ric_abilitazione ftra',
'where nvl(fta.abilitato,''S'') = ''S'' ',
'  and fta.anno = :P256_ANNO_RIACCERTAMENTO1',
'  and ftsc.capitolo_anno = fta.anno',
'  and ftsc.capitolo_eu||ftsc.capitolo_codice = fta.eu||fta.codice',
'  and ftra.user_id = apex_procedure.getIdUtente(:APP_USER)',
'  /*',
unistr('     In caso di ruolo_richiesta = ''R'' la corrispondenza della struttura \00E8 esatta, quindi controllo l''ufficio in fnd_user e se ci sono cariche ad interim.'),
unistr('     In caso di ruolo_richiesta = ''D'' la corrispondenza \00E8 solo per i primi 2 caratteri'),
'  */',
'  and ((ftsc.fin_t_strutture_codice = ftra.ufficio and ftra.ruolo_richiesta in (''R'',''DIRIGENTE'')) OR',
'       (substr(ftsc.fin_t_strutture_codice,1,2) = substr(ftra.ufficio,1,2) and ftra.ruolo_richiesta = ''D'') OR',
'       ftra.ruolo_richiesta = ''G'')',
'  and to_char(ftsc.data_assestamento, ''dd/mm/yyyy'') = ''01/01/1900''',
'  and ftsc.titolarita in (''T'',''C'')',
'order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Nessuna Selezione'
,p_lov_cascade_parent_items=>'P256_ANNO_RIACCERTAMENTO1'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>30
,p_begin_on_new_line=>'N'
,p_colspan=>2
,p_grid_column_css_classes=>'u-bold'
,p_read_only_when=>'nvl(:P256_PUO_MODIFICARE,0) = 0'
,p_read_only_when2=>'PLSQL'
,p_read_only_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(6742009815264377)
,p_item_template_options=>'#DEFAULT#'
