wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(43922553850324320)
,p_validation_name=>'Verifica importi Ufficio'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'wTotale number;',
'',
'begin',
'',
'wTotale := to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO1,0),''.'','''')) + to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO2,0),''.'','''')) ',
'          + to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO3,0),''.'','''')) + to_number(replace(nvl(:P256_IMPORTO_DA_ELIMINARE,0),''.'','''')) ',
'          + to_number(replace(nvl(:P256_IMPORTO_A_RESIDUO,0),''.'',''''));',
'',
'if wTotale <> to_number(replace(nvl(:P256_RESIDUO,0),''.'','''')) then',
'   return false;',
'end if;',
'',
'return true;',
'',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Errore: la somma degli importi nei vari anni,dell''importo da eliminare e dell''importo lasciato a residuo deve essere uguale al residuo del documento.'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P256_RUOLO != ''G'' and (',
'	nvl(:P256_PUO_MODIFICARE,0) = 1 or ',
'    nvl(:P256_PUO_MANDARE_DIR_GEN,0) = 1 or ',
'    nvl(:P256_PUO_MANDARE_UFF_BIL,0) = 1 or ',
'    :P256_STATO = 2',
')'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
