wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(43923356013324320)
,p_validation_name=>'Valida Righe Ufficio'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'werrore varchar2(500);',
'',
'begin',
'',
'if (:P256_IMPORTO_RIACCERTAMENTO1 is not null and to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO1,0),''.'','''')) != 0) or :P256_CAPITOLO_RIACCERTAMENTO1 is not null or :P256_PCF_RIACCERTAMENTO1 is not null then',
'',
'   if :P256_IMPORTO_RIACCERTAMENTO1 is null or :P256_CAPITOLO_RIACCERTAMENTO1 is null or :P256_PCF_RIACCERTAMENTO1 is null then',
'      werrore := ''Errore per l''''anno ''||:P256_ANNO_RIACCERTAMENTO1||'': non tutti i campi sono stati compilati correttamente.'';',
'   end if;',
'',
'end if;',
'',
'if (:P256_IMPORTO_RIACCERTAMENTO2 is not null and to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO2,0),''.'','''')) != 0) or :P256_CAPITOLO_RIACCERTAMENTO2 is not null or :P256_PCF_RIACCERTAMENTO2 is not null then',
'',
'   if :P256_IMPORTO_RIACCERTAMENTO2 is null or :P256_CAPITOLO_RIACCERTAMENTO2 is null or :P256_PCF_RIACCERTAMENTO2 is null then',
'      werrore := ''Errore per l''''anno ''||:P256_ANNO_RIACCERTAMENTO2||'': non tutti i campi sono stati compilati correttamente.'';',
'   end if;',
'',
'end if;',
'',
'if (:P256_IMPORTO_RIACCERTAMENTO3 is not null and to_number(replace(nvl(:P256_IMPORTO_RIACCERTAMENTO3,0),''.'','''')) != 0) or :P256_CAPITOLO_RIACCERTAMENTO3 is not null or :P256_PCF_RIACCERTAMENTO3 is not null then',
'',
'   if :P256_IMPORTO_RIACCERTAMENTO3 is null or :P256_CAPITOLO_RIACCERTAMENTO3 is null or :P256_PCF_RIACCERTAMENTO3 is null then',
'      werrore := ''Errore per l''''anno ''||:P256_ANNO_RIACCERTAMENTO3||'': non tutti i campi sono stati compilati correttamente.'';',
'   end if;',
'',
'end if;',
'',
'if werrore is not null then',
'   return werrore;',
'end if;',
'',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'nvl(:P256_PUO_MODIFICARE,0) = 1 or ',
'nvl(:P256_PUO_MANDARE_DIR_GEN,0) = 1 or ',
'nvl(:P256_PUO_MANDARE_UFF_BIL,0) = 1 or ',
'(:P256_RUOLO = ''G'' and :P256_STATO = 2)'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
