wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43929255102324311)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Aggiorna Stato Riaccertamento'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'wstato number;',
'',
'begin',
'',
'  if :P256_RUOLO = ''G'' then',
'     if :REQUEST = ''SAVE'' then',
'        :P256_STATO := 2;',
'        :P256_MESSAGGIO := ''Salvataggio avvenuto con successo'';',
'     elsif :REQUEST = ''VALIDA'' then',
'        :P256_STATO := 3;',
'     elsif :REQUEST = ''DEVALIDA'' then',
'        :P256_STATO := 2;',
'     elsif :REQUEST = ''RIT_A_DIR'' then',
'        :P256_STATO := 1;',
'         :P256_MESSAGGIO := ''Documento restituito alla Direzione Generale'';',
'     end if;',
'  elsif :P256_RUOLO = ''D'' then',
'     if :REQUEST = ''SAVE'' then',
'        :P256_STATO := 1;',
'        :P256_MESSAGGIO := ''Salvataggio avvenuto con successo'';',
'     elsif :REQUEST = ''INVIA_A_BIL'' then',
'        :P256_STATO := 2;',
'     elsif :REQUEST = ''RIT_A_UFF'' then',
'        :P256_STATO := 0;',
'        :P256_MESSAGGIO := ''Documento restituito all''''Ufficio Competente'';',
'     end if;',
'  /* 20.01.2020 Modifica aggiunta livello N.Radogna */',
'  elsif :P256_RUOLO = ''DIRIGENTE'' then',
'     if :REQUEST = ''INVIA_A_DIR'' then',
'        :P256_STATO := 1;',
'        :P256_MESSAGGIO := ''Documento inviato alla Direzione Generale'';',
'	 elsif :REQUEST = ''SAVE'' then',
'        :P256_STATO := 0;',
'        :P256_MESSAGGIO := ''Salvataggio avvenuto con successo'';',
'     end if;  ',
'  elsif :P256_RUOLO = ''R'' then',
'     if :REQUEST = ''SAVE'' then',
'        :P256_STATO := 0;',
'        :P256_MESSAGGIO := ''Salvataggio avvenuto con successo'';',
'     end if;',
'  end if;',
'',
'  update fin_t_riaccertamenti_uffici',
'  set stato = :P256_STATO',
'  where ',
'  anno_bilancio_riaccertamento = :P256_ANNO_BILANCIO',
'  and doc_id = :P256_DOC_ID;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE,VALIDA,DEVALIDA,RESPINGI,INVIA_A_DIR,INVIA_A_BIL,RIT_A_DIR, RIT_A_UFF'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>'&P256_MESSAGGIO.'
,p_internal_uid=>43929255102324311
);
