wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43926443431324318)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Setta Permessi'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'',
'wufficio varchar2(10);',
'wIncaricoAdInterim number;',
'wIncaricoRichiesteInterim number;',
'wAbilita varchar2(1);',
'',
'BEGIN',
'',
'   SELECT',
'    CASE',
'        WHEN EXISTS (',
'            SELECT 1',
'            FROM fin_t_ric_abilitazione',
'            WHERE user_id = apex_procedure.getIdUtente(:APP_USER)',
'            AND ruolo_richiesta = ''G''',
'        ) THEN ''G''',
'        WHEN EXISTS (',
'            SELECT 1',
'            FROM fin_t_ric_abilitazione',
'            WHERE user_id = apex_procedure.getIdUtente(:APP_USER)',
'            AND SUBSTR(ufficio, 1, 2) = SUBSTR(:P256_UFFICIO, 1, 2)',
'            AND ruolo_richiesta = ''D''',
'        ) THEN ''D''',
'        WHEN EXISTS (',
'            SELECT 1',
'            FROM fin_t_ric_abilitazione',
'            WHERE user_id = apex_procedure.getIdUtente(:APP_USER)',
'            AND ufficio = :P256_UFFICIO',
'            AND ruolo_richiesta IN (''R'', ''DIRIGENTE'')',
'        ) THEN (',
'            SELECT DISTINCT ruolo_richiesta',
'            FROM fin_t_ric_abilitazione',
'            WHERE user_id = apex_procedure.getIdUtente(:APP_USER)',
'            AND ufficio = :P256_UFFICIO',
'            AND ruolo_richiesta IN (''R'', ''DIRIGENTE'')',
'        )',
'        ELSE NULL',
'    END',
'INTO :P256_RUOLO',
'FROM DUAL;',
'',
'',
'   select ',
'   case',
'   when :APP_USER = ''TRACCIA'' then ''1''',
'   else RIACCERTAMENTO_SI_NO',
'   end as RIACCERTAMENTO_SI_NO',
'   into wAbilita',
'   from fin_t_dati_generali2;',
'',
'    IF :P256_RUOLO = ''R'' THEN',
'       IF NVL(:P256_STATO,0) = 0 THEN',
'          :P256_PUO_MODIFICARE := 1;',
'          :P256_PUO_MANDARE_DIR_GEN := 0;',
'       ELSE',
'          :P256_PUO_MODIFICARE := 0;',
'          :P256_PUO_MANDARE_DIR_GEN := 0;',
'       END IF;',
'       :P256_PUO_MANDARE_UFF_BIL := 0;',
'       :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'    END IF;',
'',
'',
'    IF :P256_RUOLO = ''DIRIGENTE'' THEN',
'       IF NVL(:P256_STATO,0) = 0 THEN',
'          :P256_PUO_MODIFICARE := 1;',
'          :P256_PUO_MANDARE_DIR_GEN := 1;',
'       ELSE',
'          :P256_PUO_MODIFICARE := 0;',
'          :P256_PUO_MANDARE_DIR_GEN := 0;',
'       END IF;',
'       :P256_PUO_MANDARE_UFF_BIL := 0;',
'       :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'    END IF;',
'',
'    IF :P256_RUOLO = ''D'' THEN',
'    ',
'    /* begin',
'       select ufficio',
'       into wUfficio',
'       from fnd_user',
'       where user_id = apex_procedure.getIdUtente(:APP_USER);',
'     end;',
'    ',
'     select count(*)',
'     into wIncaricoAdInterim',
'     from fin_t_cdg_dirigenti ftcd',
'        ,fnd_user fu',
'     where fu.matricola = ftcd.matricola',
'        and fu.user_id = apex_procedure.getIdUtente(:APP_USER)',
'        and ftcd.ufficio = :P256_UFFICIO;',
'    ',
'     select count(*)',
'     into wIncaricoRichiesteInterim ',
'     from fin_t_ric_abilitazione',
'     where user_id = apex_procedure.getIdUtente(:APP_USER)',
'        and ufficio = :P256_UFFICIO',
'        and ruolo_richiesta in (''R'',''D'');*/',
'    ',
'        IF NVL(:P256_STATO,0) < 2 OR NVL(:P256_STATO,0) > 0 THEN--AND --(NVL(:P256_STATO,0) > 0 OR :P256_UFFICIO = WUFFICIO OR WINCARICOADINTERIM > 0 OR WINCARICORICHIESTEINTERIM > 0) THEN',
'           :P256_PUO_MODIFICARE := 1;',
'           :P256_PUO_MANDARE_UFF_BIL := 1;',
'        ELSE',
'           :P256_PUO_MODIFICARE := 0;',
'           :P256_PUO_MANDARE_UFF_BIL := 0;',
'        END IF;',
'      :P256_PUO_MANDARE_DIR_GEN := 0;',
'      :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'    END IF;',
'',
'    IF :P256_RUOLO = ''G'' THEN',
'       IF :P256_STATO = 2 THEN',
'          :P256_PUO_MODIFICARE_UFF_BIL := 1;',
'          :P256_PUO_MANDARE_DIR_GEN := 0; --01/08/2025',
'       ELSIF :P256_STATO = 1 THEN ',
'       	  :P256_PUO_MANDARE_UFF_BIL := 1;',
'       ELSE',
'          :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'          :P256_PUO_MANDARE_DIR_GEN := 1; --01/08/2025',
'       END IF;',
unistr('    --  :P256_PUO_MANDARE_DIR_GEN := 1; 01/08/2025 se lo stato \00E8 due non deve essere mandato alla direzione generale'),
'      :P256_PUO_MODIFICARE := 1;',
'    END IF;',
'',
'   IF NVL(:P256_VALIDATO,''N'') = ''S'' AND :P256_RUOLO IS NULL THEN',
'     :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'     :P256_PUO_MANDARE_UFF_BIL := 0;',
'     :P256_PUO_MANDARE_DIR_GEN := 0;',
'     :P256_PUO_MODIFICARE := 0;',
'   ELSIF NVL(:P256_VALIDATO,''N'') = ''S'' AND :P256_RUOLO = ''G'' THEN',
'     :P256_PUO_DEVALIDARE := 1;',
unistr('     :P256_PUO_MANDARE_DIR_GEN := 0; --01/08/2025 deve prima essere devalidato non pu\00F2 essere mandato alla direzione generale'),
'   ELSE',
'     :P256_PUO_DEVALIDARE := 0;',
'   END IF;',
'',
'   IF (:P256_RUOLO IS NULL ) OR NVL(WABILITA,''S'') = ''N'' AND :P256_RUOLO != ''G'' THEN',
'     :P256_PUO_MODIFICARE_UFF_BIL := 0;',
'     :P256_PUO_MANDARE_UFF_BIL := 0;',
'     :P256_PUO_MANDARE_DIR_GEN := 0;',
'     :P256_PUO_MODIFICARE := 0;',
'     :P256_PUO_DEVALIDARE := 0;',
'   END IF;',
'',
'',
' select nvl(anno_riaccertamento,anno_esercizio_attivo1)',
' into :P256_ANNO_BILANCIO',
' from fin_t_dati_generali2;',
'',
':P256_ANNO_RIACCERTAMENTO1 := :P256_ANNO_BILANCIO;',
':P256_ANNO_RIACCERTAMENTO2 := :P256_ANNO_BILANCIO+1;',
':P256_ANNO_RIACCERTAMENTO3 := :P256_ANNO_BILANCIO+2;',
'',
' commit;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>43926443431324318
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43926832383324318)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Copertura Impegno'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'',
'',
'CURSOR accertamenti IS',
'SELECT rownum numero_riga, numero_acc, importo_vincolo, cap_entrata',
'FROM vw_vincoli_acc_imp',
'WHERE anno = :P256_ANNO_BILANCIO - 1',
'AND doc_id_imp = :P256_DOC_ID',
'AND 3>= ( SELECT COUNT(DOC_ID_ACC)',
'          FROM fin_t_vincoli_acc_imp',
'          WHERE doc_id_imp IS NOT NULL',
'          AND anno = :P256_ANNO_BILANCIO - 1',
'          AND doc_id_imp = :P256_DOC_ID)',
'ORDER BY 1;',
'',
'',
'BEGIN',
'',
'-- QUOTA ENTRATA',
' FOR a IN accertamenti LOOP',
' ',
'  IF a.numero_riga = 1',
'   THEN :P256_ACC_VINC1 := a.numero_acc;',
'        :P256_IMPORTO_ACC1 := a.importo_vincolo;',
'        :P256_CAP_VINC1 := a.cap_entrata;',
'',
'     SELECT  open_balance_proposed',
'     INTO :P256_RESIDUO_ACC1',
'     FROM fin_t_documenti',
'     WHERE doc_type = ''ACC''',
'     AND doc_sequence_value = :P256_ACC_VINC1;',
'',
'  ELSIF a.numero_riga = 2',
'   THEN :P256_ACC_VINC2 := a.numero_acc;',
'        :P256_IMPORTO_ACC2 := a.importo_vincolo;',
'        :P256_CAP_VINC2 := a.cap_entrata;',
'',
'     SELECT open_balance_proposed',
'     INTO :P256_RESIDUO_ACC2',
'     FROM fin_t_documenti',
'     WHERE doc_type = ''ACC''',
'     AND doc_sequence_value = :P256_ACC_VINC2;  ',
'',
'  ELSIF a.numero_riga = 3',
'   THEN :P256_ACC_VINC3 := a.numero_acc;',
'        :P256_IMPORTO_ACC3 := a.importo_vincolo;',
'        :P256_CAP_VINC3 := a.cap_entrata;',
'',
'     SELECT open_balance_proposed',
'     INTO :P256_RESIDUO_ACC3',
'     FROM fin_t_documenti',
'     WHERE doc_type = ''ACC''',
'     AND doc_sequence_value = :P256_ACC_VINC3;  ',
'',
'  END IF;',
' ',
'',
' END LOOP;',
'',
'--QUOTA FPV RIACCERTAMENTO',
'   BEGIN',
'   SELECT r.da_fpv, r.capitolo_fpv_coll, r.da_fpv2, r.capitolo_fpv_coll2, r.da_fpv3, r.capitolo_fpv_coll3',
'   INTO',
'   :P256_IMPORTO_FPV1,',
'   :P256_CAP_FPV1,',
'   :P256_IMPORTO_FPV2,',
'   :P256_CAP_FPV2,',
'   :P256_IMPORTO_FPV3,',
'   :P256_CAP_FPV3   ',
'   FROM fin_T_riaccertamenti r ',
'   WHERE r.doc_id_riaccertamento = :P256_DOC_ID',
'   AND nvl(r.flag_elimina,''N'') = ''N''',
'   AND r.tipo_documento <> ''ACC'';',
'   EXCEPTION WHEN NO_DATA_FOUND THEN :P256_CAP_FPV1      := NULL;',
'                                     :P256_IMPORTO_FPV1  := NULL;',
'                                     :P256_CAP_FPV2      := NULL;',
'                                     :P256_IMPORTO_FPV2  := NULL;',
'                                     :P256_CAP_FPV3      := NULL;',
'                                     :P256_IMPORTO_FPV3  := NULL;',
'   END;',
'',
'--QUOTA AVANZO',
'  BEGIN',
'  SELECT SUM(NVL(importo,0))',
'  INTO :P256_IMPORTO_AVANZO',
'  FROM vw_chiavi_contabili',
'  WHERE doc_id = :P256_DOC_ID',
'  AND id_attributo_chiave in (1,5);',
'  EXCEPTION WHEN NO_DATA_FOUND THEN :P256_IMPORTO_AVANZO := NULL;',
'  END;',
'--QUOTA FPV NON RIACC',
'  BEGIN',
'  SELECT SUM(NVL(importo,0))',
'  INTO :P256_IMPORTO_FPV_NON_RIACC',
'  FROM vw_chiavi_contabili',
'  WHERE doc_id = :P256_DOC_ID',
'  AND id_attributo_chiave = 2;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN :P256_IMPORTO_FPV_NON_RIACC := NULL;',
'  END;',
'',
'  ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P256_RUOLO'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'G'
,p_internal_uid=>43926832383324318
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43927651231324317)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Alert Beneficiari'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'/*22/07/2025 Cambio rispetto alla vecchia verifica: Controllo che la somma dell''importo lasciato a residuo, importo da eliminare e gli importi da riaccertare ',
'             sia uguale alla somma degli importi del beneficiari',
'			 Faccio vedere l''item con una scritta visibile*/',
'',
'wImportoRiaccertamento number(18,2);',
'wImportoDaEliminare number(18,2);',
'wImportoaResiduo number(18,2);',
'wImportoBeneficiario number(18,2);',
'',
'begin',
'',
'begin',
'',
'select ',
'nvl(ftru.importo_a_residuo,0)',
',nvl(ftru.importo_da_eliminare,0)',
',nvl(ftru.importo_riaccertamento1,0)+',
' nvl(ftru.importo_riaccertamento2,0)+',
' nvl(ftru.importo_riaccertamento3,0)',
'into',
'wImportoaResiduo',
',wImportoDaEliminare',
',wImportoRiaccertamento',
'from ',
'FIN_T_RIACCERTAMENTI_UFFICI ftru',
'where ',
'ftru.ANNO_BILANCIO_RIACCERTAMENTO = :P256_ANNO_BILANCIO',
'and ftru.DOC_ID = :P256_DOC_ID;',
'',
'end;',
'',
'begin',
'',
'select ',
'sum(ftrub.IMPORTO)',
'into',
'wImportoBeneficiario',
'from FIN_T_RIACCERTAMENTI_UFF_BEN ftrub',
'where ftrub.ANNO_BILANCIO_RIACCERTAMENTO = :P256_ANNO_BILANCIO',
'and ftrub.DOC_ID = :P256_DOC_ID;',
'',
'end;',
'',
'if wImportoaResiduo+wImportoDaEliminare+wImportoRiaccertamento-nvl(wImportoBeneficiario,0) != 0 then',
'   :P256_ALERT_BENEFICIARI := ''<span style="text-align:center;color:red;font-weight:bold;"><span aria-hidden="true" class="fa fa-stop-circle fa-2x fam-warning fam-is-danger"></span> IMPORTO BENEFICIARI NON CORRETTO</span>'';',
'else',
'   :P256_ALERT_BENEFICIARI := ''<span style="text-align:center;color:green;font-weight:bold;"><span aria-hidden="true" class="fa fa-check-square-o fa-2x"></span> IMPORTO BENEFICIARI INSERITO CORRETTAMENTE</span>'';',
'end if;',
'',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>43927651231324317
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43928086667324317)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Compilazione Automatica Accertamenti'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'begin',
'      select ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO1 is not null then r.capitolo_entr_coll',
'          else null',
'        end as capitolo1, ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO2 is not null then r.capitolo_entr_coll ',
'          else null',
'        end as capitolo2, ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO3 is not null then r.capitolo_entr_coll',
'          else null',
'        end as capitolo3',
'      INTO :P256_CAPITOLO_ENTRATE1_BIL, :P256_CAPITOLO_ENTRATE2_BIL, :P256_CAPITOLO_ENTRATE3_BIL',
'      FROM fin_t_riaccertamenti r',
'      ,fin_T_articoli a',
'      WHERE a.anno = r.anno_riaccertamento AND',
'      r.doc_id_riaccertamento = :P256_DOC_ID AND ',
'      a.eu||a.codice = r.capitolo_entr_coll;',
'exception when others then null;',
'end;',
'',
'begin',
'      select ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO1 is not null then r.capitolo_entr_coll2',
'          else null',
'        end as capitolo1, ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO2 is not null then r.capitolo_entr_coll2',
'          else null ',
'        end as capitolo2, ',
'        case ',
'          when :P256_IMPORTO_RIACCERTAMENTO3 is not null then r.capitolo_entr_coll2',
'          else null',
'        end as capitolo3',
'      INTO :P256_CAPITOLO_ENTRATE1B_BIL, :P256_CAPITOLO_ENTRATE2B_BIL, :P256_CAPITOLO_ENTRATE3B_BIL',
'      FROM fin_t_riaccertamenti r',
'      ,fin_T_articoli a',
'      WHERE a.anno = r.anno_riaccertamento AND',
'      r.doc_id_riaccertamento = :P256_DOC_ID AND ',
'      a.eu||a.codice = r.capitolo_entr_coll2;',
'exception when others then null;',
'end;    ',
'',
'begin',
'      select ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO1 is not null then r.capitolo_entr_coll3',
'          else null',
'        end as capitolo1, ',
'        case',
'          when :P256_IMPORTO_RIACCERTAMENTO2 is not null then r.capitolo_entr_coll3',
'          else null',
'        end as capitolo2, ',
'        case ',
'          when :P256_IMPORTO_RIACCERTAMENTO3 is not null then r.capitolo_entr_coll3 ',
'          else null ',
'        end as capitolo3',
'      INTO :P256_CAPITOLO_ENTRATE1C_BIL, :P256_CAPITOLO_ENTRATE2C_BIL, :P256_CAPITOLO_ENTRATE3C_BIL',
'      FROM fin_t_riaccertamenti r',
'      ,fin_T_articoli a',
'      WHERE a.anno = r.anno_riaccertamento AND ',
'      r.doc_id_riaccertamento = :P256_DOC_ID AND ',
'      a.eu||a.codice = r.capitolo_entr_coll3;--messo 3',
'exception when others then null;',
'end;',
'',
'-- ACC_COLLEGATO',
'',
'begin',
'      select d.doc_id acc1, to_char(r.da_entrate,''999G999G999G999G990D00'') --25/03/2022 G.ZACCARO INSERITO ANCHE IMPORTO',
'      into :P256_ACC_COLLEGATO_1, :P256_IMPORTO_ENTRATE1_BIL',
'      from fin_T_documenti d',
'      ,fin_t_riaccertamenti r --riacc impegno',
'      ,fin_T_riaccertamenti r2 -- riacc accertamento',
'      where r.doc_id_riaccertamento = :P256_DOC_ID',
unistr('      and r.anno_riaccertamento = :P256_ANNO_BILANCIO - 1 -- 28/02/2023 G.ZACCARO NON POSSO PRENDERE ANNO_BILANCIO_RIACCERTAMENTO = :P256_ANNO_BILANCIO - 1, perch\00E9 possono esserci riaccertamenti pi\00F9 vecchi'),
'      and r.capitolo_entr_coll = :P256_CAPITOLO_ENTRATE1_BIL',
'      and r2.doc_id = r.accertamento_coll',
'      and r2.doc_id_riaccertamento = d.doc_id',
'      and r2.anno_riaccertamento = r.anno_riaccertamento -- stesso anno riaccertamento per impegno e accertamento',
