 p_id=>wwv_flow_imp.id(43928426154324312)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Compilazione Automatica Accertamenti Non Riacc'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'conta_riga NUMBER :=0;',
'',
'cursor impegni is ',
'select v.cap_entrata, v.doc_id_acc, sum(nvl(v.importo_vincolo,0)) importo',
'from vw_vincoli_acc_imp v,',
'fin_T_documenti d',
'where v.anno = :P256_ANNO_BILANCIO - 1',
'and v.doc_id_imp = :P256_DOC_ID',
'and d.segment8 = v.anno',
'and d.doc_id = v.doc_id_Acc',
'and d.doc_type = ''ACC''',
'and nvl(d.attribute21,''N'')= ''N''-- accertamento non riaccertato',
'and nvl(d.deletion_status_flag,''N'')<>''Y''  --accertamento valido',
'-- and nvl(d.open_balance_proposed,0) = nvl(d.document_amount,0) l''accertamento non deve essere incassato neanche parzialmente; ',
unistr('and nvl(d.open_balance_proposed,0) > 0 --27/04/2022 G.ZACCARO Su richiesta di M. Ragone e L. Pierro cambio la condizione, l''accertamento viene proposto anche se \00E8 stato parzialmente incassato'),
'group by v.cap_entrata, v.doc_id_acc;',
'',
'',
'BEGIN',
'',
'FOR i in impegni LOOP',
' ',
' conta_riga := conta_riga+1;',
' ',
' IF conta_riga = 1',
' THEN',
'  BEGIN',
'       select ',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO1 is not null then i.cap_entrata',
'           else null',
'         end as capitolo1,',
' 		 case',
'           when :P256_IMPORTO_RIACCERTAMENTO1 is not null then i.doc_id_acc',
'           else null',
'         end as acc1,',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO1 is not null then to_char(i.importo,''999G999G999G999G990D00'')',
'           else null',
'         end as imp1,',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO2 is not null then i.cap_entrata ',
'           else null',
'         end as capitolo2,',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO2 is not null then i.doc_id_acc ',
'           else null',
'         end as acc2,',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO2 is not null then to_char(i.importo,''999G999G999G999G990D00'') ',
'           else null',
'         end as imp2,		 ',
'         case',
'           when :P256_IMPORTO_RIACCERTAMENTO3 is not null then i.cap_entrata',
